}

.social-link:hover {
    background-color: var(--accent-gold);
    color: var(--bg-primary);
    border-color: var(--accent-gold);
}

.footer-bottom {
    border-top: 1px solid var(--border-color);
    padding-top: 1.5rem;
    display: flex;
    justify-content: space-between;
    align-items: center;
    font-size: 0.85rem;
    color: var(--text-secondary);
}

.footer-bottom a {
    color: var(--text-secondary);
    text-decoration: none;
    transition: color 0.3s ease;
}

.footer-bottom a:hover {
    color: var(--accent-gold);
}

/* Responsive */
@media (max-width: 768px) {
    h1 {
        font-size: 2rem;
    }

    h2 {
        font-size: 1.75rem;
    }

    nav {
        display: none;
    }

    .container {
        padding: 0 1rem;
    }

    .hero {
        padding: 3rem 0;
    }

    .products-grid,
    .deals-grid,
    .articles-grid {
        grid-template-columns: 1fr;
    }

    .btn-secondary {
        display: block;
        margin: 1rem 0 0 0;
        width: 100%;
        text-align: center;
    }

    .newsletter-content {
        flex-direction: column;
        gap: 2rem;
    }

    .newsletter-form {
        flex-direction: column;
    }

    .newsletter-form input,
    .newsletter-form button {
        width: 100%;
    }

    .footer-bottom {
        flex-direction: column;
        gap: 1rem;
    }
}

@media (max-width: 480px) {
    h1 {
        font-size: 1.5rem;
    }

    .header-content {
        flex-wrap: wrap;
    }

    nav {
        display: none;
    }

    .products-grid {
        grid-template-columns: 1fr;
        gap: 1.5rem;
    }

    section {
        padding: 2.5rem 0;
    }

    .deal-card,
    .product-card,
    .article-card {
        padding: 1.5rem;
    }
}

/* Accessibility */
@media (prefers-reduced-motion: reduce) {
    * {
        animation-duration: 0.01ms !important;
        animation-iteration-count: 1 !important;
        transition-duration: 0.01ms !important;
    }
}

