    .product-card,
    .deal-card,
    .article-card {
        border: 1px solid CanvasText;
    }

    .btn-primary {
        background: ButtonFace;
        color: ButtonText;
        border: 1px solid ButtonText;
    }

    .section-header h2::after {
        background: CanvasText;
    }
}
