    font-size: 0.85rem;
    color: var(--text-secondary);
    margin-bottom: 1.5rem;
}

.countdown {
    display: flex;
    gap: 1rem;
    font-weight: 600;
}

.countdown-item {
    display: flex;
    flex-direction: column;
    align-items: center;
}

.countdown-value {
    font-size: 1.5rem;
    color: var(--accent-gold);
}

.countdown-label {
    font-size: 0.7rem;
    color: var(--text-secondary);
    text-transform: uppercase;
    letter-spacing: 0.5px;
}

/* Editorial Section */
.editorial {
    background-color: var(--bg-primary);
}

.articles-grid {
    display: grid;
    grid-template-columns: repeat(auto-fit, minmax(320px, 1fr));
    gap: 2.5rem;
}

.article-card {
    background-color: var(--bg-secondary);
    border: 1px solid var(--border-color);
    border-radius: 0.75rem;
    overflow: hidden;
    transition: all 0.3s ease;
    cursor: pointer;
    display: flex;
    flex-direction: column;
}

.article-card:hover {
    border-color: var(--accent-gold);
    box-shadow: var(--shadow-sm);
    transform: translateY(-5px);
}

.article-image {
    width: 100%;
    aspect-ratio: 16 / 9;
    background: linear-gradient(135deg, var(--bg-tertiary) 0%, var(--border-color) 100%);
    display: flex;
    align-items: center;
    justify-content: center;
    color: var(--text-secondary);
    font-size: 2.5rem;
    position: relative;
    overflow: hidden;
}

.article-image::after {
    content: '';
    position: absolute;
    inset: 0;
    background: rgba(212, 175, 55, 0.1);
    opacity: 0;
    transition: opacity 0.3s ease;
}

.article-card:hover .article-image::after {
    opacity: 1;
}

.article-content {
    padding: 1.75rem;
    flex: 1;
    display: flex;
    flex-direction: column;
}

.article-tag {
    color: var(--accent-gold);
    font-size: 0.8rem;
    text-transform: uppercase;
    letter-spacing: 1px;
    margin-bottom: 0.75rem;
}

.article-title {
    font-size: 1.2rem;
    margin-bottom: 0.75rem;
    flex: 1;
}

.article-excerpt {
    color: var(--text-secondary);
    font-size: 0.9rem;
    margin-bottom: 1.25rem;
}

.article-footer {
    display: flex;
    justify-content: space-between;
    align-items: center;
    padding-top: 1rem;
    border-top: 1px solid var(--border-color);
}

.article-author {
    font-size: 0.85rem;
    color: var(--text-secondary);
}

.read-more {
    color: var(--accent-gold);
    text-decoration: none;
    font-size: 0.9rem;
    font-weight: 600;
    transition: all 0.3s ease;
}

.read-more:hover {
    gap: 0.5rem;
    transform: translateX(3px);
}

/* Newsletter Section */
.newsletter {
    background: linear-gradient(135deg, var(--bg-secondary) 0%, var(--bg-tertiary) 100%);
    padding: 4rem 0;
}

.newsletter-content {
    display: flex;
    align-items: center;
    gap: 3rem;
}

.newsletter-text {
    flex: 1;
}

.newsletter-text h2 {
    margin-bottom: 1rem;
}

.newsletter-form {
    flex: 1;
    display: flex;
    gap: 1rem;
}

.newsletter-form input {
    flex: 1;
    padding: 1rem;
    background-color: var(--bg-primary);
    border: 1px solid var(--border-color);
    border-radius: 0.5rem;
    color: var(--text-primary);
    font-size: 1rem;
    transition: border-color 0.3s ease;
}

.newsletter-form input::placeholder {
    color: var(--text-secondary);
}

.newsletter-form input:focus {
    outline: none;
    border-color: var(--accent-gold);
}

.newsletter-form button {
    padding: 1rem 2rem;
    background: linear-gradient(135deg, var(--accent-gold), var(--accent-warm));
    color: var(--bg-primary);
    border: none;
    border-radius: 0.5rem;
    font-weight: 600;
    cursor: pointer;
    transition: all 0.3s ease;
    white-space: nowrap;
}

.newsletter-form button:hover {
    transform: translateY(-2px);
    box-shadow: 0 15px 30px rgba(212, 175, 55, 0.3);
}

/* Footer */
footer {
    background-color: var(--bg-secondary);
    border-top: 1px solid var(--border-color);
    padding: 3rem 0 1.5rem;
}

.footer-content {
    display: grid;
    grid-template-columns: repeat(auto-fit, minmax(250px, 1fr));
    gap: 2rem;
    margin-bottom: 2.5rem;
}

.footer-section h4 {
    margin-bottom: 1.25rem;
    color: var(--text-primary);
}

.footer-section ul {
    list-style: none;
}

.footer-section ul li {
    margin-bottom: 0.75rem;
}

.footer-section a {
    color: var(--text-secondary);
    text-decoration: none;
    transition: color 0.3s ease;
    font-size: 0.9rem;
}

.footer-section a:hover {
    color: var(--accent-gold);
}

.footer-section.social {
    display: flex;
    gap: 1rem;
}

.social-link {
    width: 40px;
    height: 40px;
    background-color: var(--bg-tertiary);
    border: 1px solid var(--border-color);
    border-radius: 50%;
    display: flex;
    align-items: center;
    justify-content: center;
    color: var(--text-primary);
    cursor: pointer;
    transition: all 0.3s ease;
}

.social-link:hover {
    background-color: var(--accent-gold);
    color: var(--bg-primary);
    border-color: var(--accent-gold);
}

.footer-bottom {
    border-top: 1px solid var(--border-color);
    padding-top: 1.5rem;
    display: flex;
    justify-content: space-between;
    align-items: center;
    font-size: 0.85rem;
    color: var(--text-secondary);
}

.footer-bottom a {
    color: var(--text-secondary);
    text-decoration: none;
    transition: color 0.3s ease;
}

.footer-bottom a:hover {
    color: var(--accent-gold);
}

/* Responsive */
@media (max-width: 768px) {
    h1 {
        font-size: 2rem;
    }

    h2 {
        font-size: 1.75rem;
    }

    nav {
        display: none;
    }

    .container {
        padding: 0 1rem;
    }

    .hero {
        padding: 3rem 0;
    }

    .products-grid,
    .deals-grid,
    .articles-grid {
        grid-template-columns: 1fr;
    }

    .btn-secondary {
        display: block;
        margin: 1rem 0 0 0;
        width: 100%;
        text-align: center;
    }

    .newsletter-content {
        flex-direction: column;
        gap: 2rem;
    }

    .newsletter-form {
        flex-direction: column;
    }

    .newsletter-form input,
    .newsletter-form button {
        width: 100%;
    }

    .footer-bottom {
        flex-direction: column;
        gap: 1rem;
    }
}

@media (max-width: 480px) {
    h1 {
        font-size: 1.5rem;
    }

    .header-content {
        flex-wrap: wrap;
    }

    nav {
        display: none;
    }

    .products-grid {
        grid-template-columns: 1fr;
        gap: 1.5rem;
    }

    section {
        padding: 2.5rem 0;
    }

    .deal-card,
    .product-card,
    .article-card {
        padding: 1.5rem;
    }
}

/* Accessibility */
@media (prefers-reduced-motion: reduce) {
    * {
        animation-duration: 0.01ms !important;
        animation-iteration-count: 1 !important;
        transition-duration: 0.01ms !important;
    }
}

@media (forced-colors: active) {
    .product-card,
    .deal-card,
    .article-card {
        border: 1px solid CanvasText;
    }

    .btn-primary {
        background: ButtonFace;
        color: ButtonText;
        border: 1px solid ButtonText;
    }

    .section-header h2::after {
        background: CanvasText;
    }
}

