        const deal = this.state.deals.find(d => d.id === dealId);
        alert(`Viewing deal: ${deal.title}`);
    },

    handleReadArticle: function(event, articleId) {
        event.preventDefault();
        const article = this.state.articles.find(a => a.id === articleId);
        alert(`Reading: ${article.title}`);
    },

    handleNewsletterSubmit: function(event) {
        event.preventDefault();
        const email = event.target.querySelector('input[type="email"]').value;
        this.showNotification(`Subscribed with ${email}!`);
        event.target.reset();
    },

    updateCartBadge: function() {
        const badge = document.querySelector('.cart-badge');
        if (badge) {
            badge.textContent = this.state.cartCount;
        } else if (this.state.cartCount > 0) {
            this.render();
        }
    },

    showNotification: function(message) {
        const notification = document.createElement('div');
        notification.textContent = message;
        notification.style.cssText = `
            position: fixed;
            bottom: 2rem;
            right: 2rem;
            background: linear-gradient(135deg, #d4af37, #e8b76e);
            color: #0f0f0f;
            padding: 1rem 1.5rem;
            border-radius: 0.5rem;
            font-weight: 600;
            box-shadow: 0 10px 30px rgba(0, 0, 0, 0.5);
            z-index: 1000;
            animation: slideIn 0.3s ease;
        `;
        document.body.appendChild(notification);
        setTimeout(() => {
            notification.style.animation = 'slideOut 0.3s ease';
            setTimeout(() => notification.remove(), 300);
        }, 3000);
    },

    // Initialize App
    init: function() {
        this.render();
        this.addKeyboardSupport();
        this.addAnimationStyles();
    },

    addKeyboardSupport: function() {
        document.addEventListener('keydown', (e) => {
            if (e.key === 'Escape') {
                // Can be used for closing modals/dialogs
            }
        });
    },

    addAnimationStyles: function() {
        const style = document.createElement('style');
        style.textContent = `
            @keyframes slideIn {
                from {
                    transform: translateX(400px);
                    opacity: 0;
                }
                to {
                    transform: translateX(0);
                    opacity: 1;
                }
            }
            @keyframes slideOut {
                from {
                    transform: translateX(0);
                    opacity: 1;
                }
                to {
                    transform: translateX(400px);
                    opacity: 0;
                }
            }
        `;
        document.head.appendChild(style);
    }
};

// Initialize app when DOM is ready
document.addEventListener('DOMContentLoaded', () => app.init());

