+}
+
+.countdown-item {
+    display: flex;
+    flex-direction: column;
+    align-items: center;
+}
+
+.countdown-value {
+    font-size: 1.5rem;
+    color: var(--accent-gold);
+}
+
+.countdown-label {
+    font-size: 0.7rem;
+    color: var(--text-secondary);
+    text-transform: uppercase;
+    letter-spacing: 0.5px;
+}
+
+/* Editorial Section */
+.editorial {
+    background-color: var(--bg-primary);
+}
+
+.articles-grid {
+    display: grid;
