+    letter-spacing: 1px;
+    margin-bottom: 0.75rem;
+}
+
+.article-title {
+    font-size: 1.2rem;
+    margin-bottom: 0.75rem;
+    flex: 1;
+}
+
+.article-excerpt {
+    color: var(--text-secondary);
